/* =============================================================================
   Boppa Llewyn × Starlight

   The Boppa Llewyn design system on Starlight, the theme Doctored's documentation
   site wears (its public-docs/src/styles/custom.css), carried over rule for rule so
   the two sites look like one family; only Prettier's formatting differs. Change it there and here together. Frame Job's own
   components are styled in frame-job.css, which loads after this file.

   This file is unlayered, so it wins over every Starlight cascade layer. The
   @font-face rules are in src/fonts/font-face.css and the Expressive Code settings
   in astro.config.mjs.
   ============================================================================= */

/* --- Boppa Llewyn tokens, verbatim from the design system --------------- */
:root {
  --bl-cream: #fbf8f1;
  --bl-cream-1: #f4efe2;
  --bl-cream-2: #eae3d2;
  --bl-ink: #101915;
  --bl-on-cream-2: #40483f;
  --bl-on-cream-3: #6b7268;

  --bl-bg-0: oklch(0.16 0.011 70);
  --bl-bg-1: oklch(0.195 0.012 70);
  --bl-bg-2: oklch(0.23 0.013 70);
  --bl-bg-3: oklch(0.275 0.014 70);
  --bl-line-1: oklch(0.32 0.015 72);
  --bl-line-2: oklch(0.43 0.018 75);
  --bl-fg-1: oklch(0.94 0.014 88);
  --bl-fg-2: oklch(0.74 0.02 82);
  --bl-fg-3: oklch(0.57 0.018 78);

  --bl-brass: #f2c14e;
  --bl-brass-strong: #e0ab33;
  --bl-brass-dim: oklch(0.3 0.05 84);
  --bl-brass-faint: oklch(0.225 0.028 84);

  --bl-teal: #1f8564;
  --bl-teal-dim: oklch(0.26 0.04 165);
  --bl-ember: #f4653f;
  --bl-ember-dim: oklch(0.27 0.05 40);
  --bl-danger: oklch(0.63 0.14 25);
  --bl-danger-dim: oklch(0.25 0.05 25);

  /* darkened brass for cream surfaces — brass itself fails contrast on cream */
  --bl-brass-deep: #8a6410;
  --bl-brass-deeper: #5c4208;
  --bl-brass-pale: #f7e9c5;

  --bl-radius-1: 2px;
  --bl-radius-2: 4px;
  --bl-radius-3: 8px;
  --bl-ease: cubic-bezier(0.2, 0.8, 0.2, 1);
  --bl-dur-fast: 120ms;
  --bl-dur-base: 200ms;

  --bl-font-display: 'Cormorant Garamond', Georgia, 'Times New Roman', serif;
}

/* --- Type and layout ---------------------------------------------------- */
:root {
  --sl-font: 'IBM Plex Sans', system-ui, sans-serif;
  --sl-font-mono: 'IBM Plex Mono', ui-monospace, monospace;

  --sl-text-body: 0.9375rem; /* 15px */
  --sl-text-body-sm: 0.8125rem; /* 13px */
  --sl-text-code: 0.8125rem;
  --sl-text-code-sm: 0.75rem;
  --sl-line-height: 1.55;
  --sl-line-height-headings: 1.06;

  /* Cormorant sits small on its em, so display sizes run large */
  --sl-text-h1: 2.625rem;
  --sl-text-h2: 1.875rem;
  --sl-text-h3: 1.5rem;
  --sl-text-h4: 1.25rem;
  --sl-text-h5: 1.0625rem;

  --sl-nav-height: 3.75rem; /* 60px, per the site header */
  --sl-sidebar-width: 17.5rem;
  --sl-content-width: 42.5rem; /* --measure-prose, 680px */
}

@media (min-width: 50em) {
  :root {
    --sl-nav-height: 3.75rem;
    --sl-nav-pad-x: 1.5rem;
    --sl-text-h1: 3.25rem; /* 52px, --text-3xl */
    --sl-text-h2: 2.375rem; /* 38px */
    --sl-text-h3: 1.75rem;
    --sl-text-h4: 1.3125rem;
  }
}

/* --- Colour: dark (default) --------------------------------------------- */
:root,
::backdrop {
  --sl-color-white: var(--bl-fg-1);
  --sl-color-gray-1: var(--bl-fg-1);
  --sl-color-gray-2: var(--bl-fg-2);
  --sl-color-gray-3: var(--bl-fg-3);
  --sl-color-gray-4: var(--bl-line-2);
  --sl-color-gray-5: var(--bl-bg-3);
  --sl-color-gray-6: var(--bl-bg-1);
  --sl-color-gray-7: var(--bl-bg-2);
  --sl-color-black: var(--bl-bg-0);

  --sl-color-accent-low: var(--bl-brass-faint);
  --sl-color-accent: var(--bl-brass);
  --sl-color-accent-high: var(--bl-brass);

  --sl-color-text: var(--bl-fg-2);
  --sl-color-text-accent: var(--bl-brass);
  --sl-color-text-invert: var(--bl-ink);
  --sl-color-bg: var(--bl-bg-0);
  --sl-color-bg-nav: var(--bl-bg-0);
  --sl-color-bg-sidebar: var(--bl-bg-1);
  --sl-color-bg-inline-code: var(--bl-bg-2);
  --sl-color-bg-accent: var(--bl-brass);
  --sl-color-hairline-light: var(--bl-line-1);
  --sl-color-hairline: var(--bl-line-1);
  --sl-color-hairline-shade: var(--bl-line-1);
  --sl-color-backdrop-overlay: rgba(10, 9, 8, 0.65);

  /* Aside hues remapped onto the palette: note→teal, tip→brass,
     caution→ember, danger→danger. Starlight has no separate green/blue use. */
  --sl-color-blue-low: var(--bl-teal-dim);
  --sl-color-blue: var(--bl-teal);
  --sl-color-blue-high: #8ad8b9;
  --sl-color-green-low: var(--bl-teal-dim);
  --sl-color-green: var(--bl-teal);
  --sl-color-green-high: #8ad8b9;
  --sl-color-purple-low: var(--bl-brass-faint);
  --sl-color-purple: var(--bl-brass);
  --sl-color-purple-high: var(--bl-brass);
  --sl-color-orange-low: var(--bl-ember-dim);
  --sl-color-orange: var(--bl-ember);
  --sl-color-orange-high: #ffa487;
  --sl-color-red-low: var(--bl-danger-dim);
  --sl-color-red: var(--bl-danger);
  --sl-color-red-high: #f6aa9e;

  /* Shadows exist for true overlays only */
  --sl-shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.4);
  --sl-shadow-md: 0 4px 16px rgba(0, 0, 0, 0.45);
  --sl-shadow-lg: 0 16px 48px rgba(0, 0, 0, 0.55);
}

/* --- Colour: cream (light) --------------------------------------------- */
:root[data-theme='light'],
[data-theme='light'],
[data-theme='light'] ::backdrop {
  --sl-color-white: var(--bl-ink);
  --sl-color-gray-1: #1a2620;
  --sl-color-gray-2: var(--bl-on-cream-2);
  --sl-color-gray-3: var(--bl-on-cream-3);
  --sl-color-gray-4: #98a093;
  --sl-color-gray-5: var(--bl-cream-2);
  --sl-color-gray-6: var(--bl-cream-1);
  --sl-color-gray-7: #f8f5ec;
  --sl-color-black: var(--bl-cream);

  --sl-color-accent-low: var(--bl-brass-pale);
  --sl-color-accent: var(--bl-brass-deep);
  --sl-color-accent-high: var(--bl-brass-deeper);

  --sl-color-text: var(--bl-on-cream-2);
  --sl-color-text-accent: var(--bl-brass-deep);
  --sl-color-text-invert: var(--bl-cream);
  --sl-color-bg: var(--bl-cream);
  --sl-color-bg-nav: var(--bl-cream);
  --sl-color-bg-sidebar: var(--bl-cream-1);
  --sl-color-bg-inline-code: var(--bl-cream-2);
  --sl-color-bg-accent: var(--bl-brass-deep);
  --sl-color-hairline-light: rgba(16, 25, 21, 0.14);
  --sl-color-hairline: rgba(16, 25, 21, 0.14);
  --sl-color-hairline-shade: rgba(16, 25, 21, 0.14);
  --sl-color-backdrop-overlay: rgba(16, 25, 21, 0.5);

  --sl-color-blue-low: #dcefe7;
  --sl-color-blue: var(--bl-teal);
  --sl-color-blue-high: #0e5540;
  --sl-color-green-low: #dcefe7;
  --sl-color-green: var(--bl-teal);
  --sl-color-green-high: #0e5540;
  --sl-color-purple-low: var(--bl-brass-pale);
  --sl-color-purple: var(--bl-brass-deep);
  --sl-color-purple-high: var(--bl-brass-deeper);
  --sl-color-orange-low: #fbded4;
  --sl-color-orange: var(--bl-ember);
  --sl-color-orange-high: #8a3116;
  --sl-color-red-low: #f8ddd7;
  --sl-color-red: #b03a22;
  --sl-color-red-high: #8c2a1c;

  --sl-shadow-sm: 0 1px 2px rgba(16, 25, 21, 0.1);
  --sl-shadow-md: 0 4px 16px rgba(16, 25, 21, 0.12);
  --sl-shadow-lg: 0 16px 48px rgba(16, 25, 21, 0.18);
}

/* --- Display type ------------------------------------------------------- */
:is(.sl-markdown-content, .content-panel, .hero, .card, .sl-link-card) :is(h1, h2, h3, h4),
.content-panel h1,
.hero h1,
.site-title {
  font-family: var(--bl-font-display);
  font-weight: 500;
  letter-spacing: -0.005em;
  line-height: 1.06;
  color: var(--sl-color-white);
}

/* h5/h6 stay in the sans — small serif does not hold up */
.sl-markdown-content :is(h5, h6) {
  font-family: var(--sl-font);
  font-weight: 600;
  letter-spacing: 0;
}

.site-title {
  font-size: 1.375rem;
}

/* Mono eyebrows: sidebar group labels, table headers, code captions, ToC label */
.sidebar-content .group-label .large,
.right-sidebar h2,
/* Starlight 0.42 builds the mobile ToC from <details>/<summary>, not the
   <button> this file was written against, and the host is the custom element
   itself rather than a class. `.display-current` is the label that carries the
   current section, which is the one the design sets in mono. */
mobile-starlight-toc .display-current,
.sl-markdown-content th,
.expressive-code figcaption .title,
.starlight-aside__title {
  font-family: var(--sl-font-mono);
  font-weight: 500;
  font-size: 0.75rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

/* Prices, versions, badges, fine print */
.sl-markdown-content kbd,
.sl-markdown-content code {
  font-size: 0.8125rem;
  border-radius: var(--bl-radius-1);
}

/* --- Joinery corners, borders over shadows ----------------------------- */
.card,
.sl-link-card,
.starlight-aside,
.expressive-code .frame,
.sl-link-button,
.right-sidebar-panel details {
  border-radius: var(--bl-radius-2);
}

input,
select,
.search-input,
site-search button {
  border-radius: var(--bl-radius-1);
}

dialog,
.dialog-frame,
starlight-toc details {
  border-radius: var(--bl-radius-3);
}

.card,
.sl-link-card {
  background-color: var(--sl-color-gray-6);
  border: 1px solid var(--sl-color-hairline-light);
  box-shadow: none;
}

.sl-link-card:hover {
  background-color: var(--sl-color-gray-7);
  border-color: var(--sl-color-gray-4);
  box-shadow: none;
}

/* --- Asides: hairline box + mono eyebrow, not a left accent bar --------- */
.starlight-aside {
  border: 1px solid var(--sl-color-asides-border);
  border-inline-start-width: 1px;
  padding: 1rem 1.25rem;
  color: var(--sl-color-gray-1);
}

.starlight-aside__icon {
  display: none;
}

.starlight-aside__title {
  color: var(--sl-color-asides-text-accent);
  line-height: 1;
}

/* --- Code blocks -------------------------------------------------------- */
.expressive-code .frame {
  border: 1px solid var(--sl-color-hairline-light);
  overflow: hidden;
}

.expressive-code .frame pre {
  background: var(--sl-color-gray-6);
  border: 0;
  font-size: 0.8125rem;
  line-height: 1.6;
}

/* --- Tables ------------------------------------------------------------- */
.sl-markdown-content table {
  border-collapse: collapse;
  width: 100%;
  font-size: 0.875rem;
}

.sl-markdown-content :is(th, td) {
  border: 0;
  border-bottom: 1px solid var(--sl-color-hairline-light);
  padding: 0.625rem 0.75rem;
  text-align: start;
}

.sl-markdown-content th {
  color: var(--sl-color-gray-3);
}

/* --- Header: the one blurred surface in the system ---------------------- */
header.header {
  background-color: color-mix(in srgb, var(--sl-color-bg) 85%, transparent);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--sl-color-hairline-shade);
}

/* --- Links, buttons, motion -------------------------------------------- */
.sl-markdown-content a:not(:where(.sl-link-card, .sl-link-button, .not-content *)) {
  color: var(--sl-color-text-accent);
  text-decoration: none;
  text-underline-offset: 0.2em;
  transition: color var(--bl-dur-fast) var(--bl-ease);
}

.sl-markdown-content a:not(:where(.sl-link-card, .sl-link-button, .not-content *)):hover {
  color: var(--sl-color-accent-high);
  text-decoration: underline;
}

.sl-link-button.primary {
  background: var(--bl-brass);
  color: var(--bl-ink);
  border: 1px solid transparent;
  font-weight: 500;
}

.sl-link-button.primary:hover {
  background: var(--bl-brass-strong);
  color: var(--bl-ink);
  text-decoration: none;
}

.sl-link-button.secondary {
  background: var(--sl-color-gray-6);
  color: var(--sl-color-white);
  border: 1px solid var(--sl-color-hairline-light);
}

.sl-link-button.secondary:hover {
  background: var(--sl-color-gray-7);
  border-color: var(--sl-color-gray-4);
}

.sl-link-button.minimal {
  color: var(--sl-color-text-accent);
}

/* Nothing scales or shrinks; opacity and colour only */
a,
button,
summary,
.sl-link-card {
  transition:
    background-color var(--bl-dur-fast) var(--bl-ease),
    border-color var(--bl-dur-fast) var(--bl-ease),
    color var(--bl-dur-fast) var(--bl-ease);
}

/* --- Focus: 2px page-coloured offset plus a 4px brass ring ------------- */
:is(a, button, summary, input, select, [tabindex]):focus-visible {
  outline: none;
  box-shadow:
    0 0 0 2px var(--sl-color-bg),
    0 0 0 4px var(--sl-color-accent);
  border-radius: var(--bl-radius-1);
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition-duration: 0.01ms !important;
  }
}

/* =============================================================================
   Site layer — the parts of the design the token file above cannot reach.

   Everything here is unlayered too, so it beats Starlight's own
   `starlight.core` / `starlight.components` / `starlight.content` layers
   regardless of specificity. Values come from the handoff's screen notes;
   where the notes and `starlight-custom.css` disagree, the CSS above wins.
   ============================================================================= */

/* --- Layout metrics ----------------------------------------------------- */
:root {
  --sl-content-pad-x: 1.5rem; /* 24px gutter, the design's container inset */
}

/* Splash pages (no sidebar) run to the design's 1120px container rather than
   Starlight's 1080px. The extra `[data-has-hero]` lifts specificity over the
   `html:not([data-has-sidebar])` rule Starlight inlines in <head>. */
html[data-has-hero]:not([data-has-sidebar]) {
  --sl-content-width: 70rem;
}

/* --- Header controls ---------------------------------------------------- */
/* The mobile menu button ships as a filled circle with a shadow. The system
   has no filled circles and no shadows outside true overlays, so it becomes a
   32px hairline square. 32px is under the 44px minimum touch target, so the
   hit area is expanded past the visual box with a pseudo-element. */
.sl-menu-button {
  border: 1px solid var(--sl-color-hairline-light);
  border-radius: var(--bl-radius-1);
  background-color: var(--sl-color-bg);
  color: var(--sl-color-gray-1);
  box-shadow: none;
}

.sl-menu-button:hover {
  background-color: var(--sl-color-gray-6);
  border-color: var(--sl-color-gray-4);
  color: var(--sl-color-white);
}

.sl-menu-button:has(~ :popover-open) {
  background-color: var(--sl-color-gray-6);
  border-color: var(--sl-color-gray-4);
  color: var(--sl-color-white);
  box-shadow: none;
}

/* 32px box, 44px target: the pseudo-element is the thing the finger hits. */
.sl-menu-button::after {
  content: '';
  position: absolute;
  inset: calc((var(--sl-menu-button-size) - 2.75rem) / 2);
}

/* Below the sidebar breakpoint the search control is an icon button; the design
   draws it as a 32px hairline square, again with a 44px hit area. */
@media (max-width: 50rem) {
  site-search button[data-open-modal] {
    position: relative;
    width: var(--sl-menu-button-size);
    height: var(--sl-menu-button-size);
    justify-content: center;
    padding: 0;
    border: 1px solid var(--sl-color-hairline-light);
    border-radius: var(--bl-radius-1);
    background-color: transparent;
    color: var(--sl-color-gray-1);
  }

  site-search button[data-open-modal]::after {
    content: '';
    position: absolute;
    inset: calc((var(--sl-menu-button-size) - 2.75rem) / 2);
  }

  site-search button[data-open-modal] svg {
    font-size: 1rem;
  }
}

/* --- Sidebar ------------------------------------------------------------ */
.sidebar-content {
  padding: 2rem var(--sl-sidebar-pad-x);
}

/* 28px between top-level groups */
.sidebar-content .top-level > li + li {
  margin-top: 1.75rem;
}

.sidebar-content .group-label .large {
  color: var(--sl-color-gray-3);
}

.sidebar-content summary {
  padding-inline: var(--sl-sidebar-item-padding-inline, 0.5rem);
}

.sidebar-content a {
  font-size: var(--sl-text-sm);
  padding: 0.375rem 0.5rem;
  border-radius: var(--bl-radius-2);
}

/* Guarded against `[aria-current]` so the brass current-page pill survives a
   hover — an unlayered `a:hover` would otherwise outrank Starlight's rule. */
.sidebar-content a:not([aria-current='page']):is(:hover, :focus-visible) {
  background-color: var(--sl-color-gray-6);
  color: var(--sl-color-white);
}

/* --- Table of contents -------------------------------------------------- */
.right-sidebar-panel h2 {
  color: var(--sl-color-gray-3);
  margin-bottom: 0.75rem;
}

.right-sidebar-panel nav > ul {
  border-inline-start: 1px solid var(--sl-color-hairline-light);
}

.right-sidebar-panel nav a {
  --pad-inline: 0.75rem; /* + the 2px rail below = the design's 14px */
  border-radius: 0;
  border-inline-start: 2px solid transparent;
  margin-inline-start: -1px; /* sit the rail on top of the list hairline */
  font-size: var(--sl-text-xs);
  padding-block: 0.3125rem;
}

.right-sidebar-panel nav a[aria-current='true'] {
  border-inline-start-color: var(--sl-color-accent);
  color: var(--sl-color-white);
}

/* Mobile ToC bar: a flat 48px strip, not a bordered pill in a bar. */
mobile-starlight-toc nav {
  background-color: var(--sl-color-bg-sidebar);
  border-top: 0;
}

mobile-starlight-toc summary {
  border-bottom: 1px solid var(--sl-color-hairline-light);
  font-size: var(--sl-text-sm);
  padding-inline: var(--sl-content-pad-x);
}

mobile-starlight-toc .toggle {
  border: 0;
  border-radius: 0;
  background-color: transparent;
  padding-inline: 0;
  gap: 0.5rem;
}

mobile-starlight-toc .toggle .caret {
  order: -1; /* chevron leads the label, as drawn */
}

mobile-starlight-toc details[open] .toggle {
  border-color: transparent;
  color: var(--sl-color-white);
}

mobile-starlight-toc .display-current {
  margin-inline-start: auto; /* the design parks it at the end of the bar */
  font-size: 0.6875rem; /* 11px */
  color: var(--sl-color-gray-3);
}

mobile-starlight-toc .dropdown {
  background-color: var(--sl-color-bg-sidebar);
  border-color: var(--sl-color-hairline-light);
  box-shadow: none;
}

/* --- The page opener ---------------------------------------------------- */
/* Sections breathe: 56px above the title, 144px below the last block. The
   hairline between the two panels is Starlight's own and is already token'd. */
.content-panel {
  padding-block: 2rem;
}

.content-panel:first-of-type {
  padding-block-start: 3.5rem;
}

.content-panel:last-of-type {
  padding-block-end: 9rem;
}

.page-eyebrow {
  font-family: var(--sl-font-mono);
  font-weight: 500;
  font-size: 0.75rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--sl-color-accent);
}

.page-description {
  font-size: 1.0625rem; /* 17px */
  line-height: 1.5;
  color: var(--sl-color-gray-2);
}

/* --- Splash ------------------------------------------------------------- */
@media (min-width: 50rem) {
  .hero {
    grid-template-columns: minmax(0, 1fr) 300px;
    gap: 4rem;
    padding-block: 7rem 6rem;
  }

  .hero > img,
  .hero > .hero-html {
    width: 300px;
    margin-inline-start: auto;
  }
}

.hero h1 {
  font-size: clamp(3.25rem, 7vw, 5.5rem);
}

.hero .tagline {
  font-size: 1.1875rem; /* 19px */
  line-height: 1.5;
  max-width: 44ch;
}

.hero .actions {
  gap: 1rem;
}

/* The hero pads itself 112/96, so the panel contributes nothing above it; the
   144px below the last block stays with the panel. */
[data-has-hero] .content-panel {
  padding-block: 0 9rem;
}

/* A hairline, then "Next steps" — 80px above it. */
[data-has-hero] .content-panel .sl-markdown-content {
  margin-top: 0;
  border-top: 1px solid var(--sl-color-hairline-light);
  padding-block: 5rem 0;
}

/* --- Cards -------------------------------------------------------------- */
.card-grid {
  gap: 1.25rem;
}

@media (min-width: 50rem) {
  .card-grid {
    gap: 1.25rem;
  }

  .card-grid.stagger {
    --stagger-height: 3rem;
  }
}

.card,
.sl-link-card {
  padding: 1.5rem;
}

.card {
  gap: 0.75rem;
}

.sl-link-card .title {
  font-family: var(--bl-font-display);
  font-weight: 500;
  font-size: var(--sl-text-h4);
  letter-spacing: -0.005em;
  line-height: 1.06;
}

/* Starlight's Card title is a <p>, so the display-type rule above misses it. */
.card .title {
  font-family: var(--bl-font-display);
  font-weight: 500;
  font-size: 1.5rem;
  letter-spacing: -0.005em;
  line-height: 1.06;
  gap: 0.75rem;
}

/* The stock icon chip cycles four hues by position. The system has one accent,
   so the chip is a hairline box and the mark is brass. */
.card .icon {
  border-color: var(--sl-color-hairline-light);
  background-color: transparent;
  border-radius: var(--bl-radius-1);
  color: var(--sl-color-accent);
}

.card .body {
  font-size: var(--sl-text-sm);
  line-height: 1.55;
  color: var(--sl-color-gray-2);
}

/* --- Buttons ------------------------------------------------------------ */
.sl-link-button {
  font-size: var(--sl-text-body);
  padding: 0.6875rem 1.375rem; /* 11px 22px */
}

@media (min-width: 50rem) {
  .sl-link-button {
    font-size: var(--sl-text-body);
    padding: 0.6875rem 1.375rem;
  }
}

.sl-link-button.minimal {
  padding-inline: 0;
}

.sl-link-button svg {
  width: 1rem;
  height: 1rem;
}

/* --- Code, tables, kbd -------------------------------------------------- */
.expressive-code figcaption {
  background-color: var(--sl-color-gray-6);
  border-bottom: 1px solid var(--sl-color-hairline-light);
}

.sl-markdown-content pre:not(:where(.not-content *)) {
  border-color: var(--sl-color-hairline-light);
  border-radius: var(--bl-radius-2);
}

.sl-markdown-content blockquote:not(:where(.not-content *)) {
  border-inline-start-color: var(--sl-color-hairline-light);
}

/* Starlight makes tables `display: block` so wide ones scroll on their own.
   The design asks for a full-width table instead, which needs a real table box. */
.sl-markdown-content table:not(:where(.not-content *)) {
  display: table;
  width: 100%;
}

/* Commands and identifiers in tables never break mid-token. */
.sl-markdown-content :is(th, td) > code {
  white-space: nowrap;
}

.sl-markdown-content kbd {
  font-family: var(--sl-font-mono);
  background-color: var(--sl-color-gray-5);
  border: 1px solid var(--sl-color-hairline-light);
  padding: 0.125rem 0.375rem;
}

/* --- Footer ------------------------------------------------------------- */
/* Footer fine print is mono and factual. Nothing renders here until `editLink`
   or `lastUpdated` is switched on in the Starlight config; this is so that it
   arrives already themed when it is. */
footer .meta,
footer .kudos {
  font-family: var(--sl-font-mono);
  font-size: 0.75rem;
  color: var(--sl-color-gray-3);
}

/* --- Pagination --------------------------------------------------------- */
/* The prev/next links are cards, and cards take a hairline and no shadow. */
.pagination-links a {
  border-radius: var(--bl-radius-2);
  border-color: var(--sl-color-hairline-light);
  box-shadow: none;
}

.pagination-links a:hover {
  background-color: var(--sl-color-gray-6);
  border-color: var(--sl-color-gray-4);
}

.pagination-links .link-title {
  color: var(--sl-color-white);
  font-size: var(--sl-text-h4);
}

/* --- Search ------------------------------------------------------------- */
site-search kbd {
  font-family: var(--sl-font-mono);
  border-radius: var(--bl-radius-1);
}

site-search button[data-open-modal] {
  background-color: var(--sl-color-gray-6);
  border-color: var(--sl-color-hairline-light);
}

site-search button[data-open-modal]:hover {
  background-color: var(--sl-color-gray-7);
  border-color: var(--sl-color-gray-4);
  color: var(--sl-color-white);
}

#starlight__search {
  --pagefind-ui-border-radius: var(--bl-radius-1);
  --pagefind-ui-background: var(--sl-color-gray-6);
  --pagefind-ui-border: var(--sl-color-hairline-light);
}

#starlight__search input:focus {
  --pagefind-ui-border: var(--sl-color-accent);
}

content.content:
/* Frame Job's own components in the Boppa Llewyn theme (boppa-llewyn.css, which loads first and
   holds every token used here): hairline boxes instead of shadows and accent bars, mono uppercase
   eyebrows for labels, and the system's small radii. Unlayered, like the theme. */

/* ---- Screens: both looks are in the page, the theme shows one. ---- */

.fj-shot {
  margin-block: 1.5rem;
}

.fj-shot img {
  display: block;
  width: 100%;
  height: auto;
  border: 1px solid var(--sl-color-hairline-light);
  border-radius: var(--bl-radius-1);
}

.fj-shot figcaption {
  margin-top: 0.5rem;
  color: var(--sl-color-gray-3);
  font-size: var(--sl-text-sm);
}

:root[data-theme='light'] .fj-shot .fj-dark,
:root:not([data-theme='light']) .fj-shot .fj-light {
  display: none;
}

/* ---- Keys, as the app prints them: ⌘T. The theme styles the key cap itself. ---- */

.sl-markdown-content kbd {
  white-space: nowrap;
}

/* ---- At a glance: a hairline box, its labels mono eyebrows. ---- */

.fj-glance {
  display: grid;
  grid-template-columns: max-content 1fr;
  align-items: baseline;
  gap: 0.5rem 1.5rem;
  margin-block: 1.5rem;
  padding: 1rem 1.25rem;
  background-color: var(--sl-color-gray-6);
  border: 1px solid var(--sl-color-hairline-light);
  border-radius: var(--bl-radius-2);
  font-size: var(--sl-text-sm);
  color: var(--sl-color-gray-1);
}

.fj-glance dt {
  margin: 0;
  font-family: var(--sl-font-mono);
  font-weight: 500;
  font-size: 0.75rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--sl-color-gray-3);
}

.fj-glance dd {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem 1rem;
  margin: 0;
}

.fj-glance strong {
  font-weight: 600;
  color: var(--sl-color-white);
}

.fj-glance code {
  font-size: 0.8125rem;
  background-color: var(--sl-color-bg-inline-code);
  border-radius: var(--bl-radius-1);
  padding: 0.0625rem 0.3125rem;
}

/* ---- The feature index ---- */

.fj-filter {
  position: sticky;
  top: calc(var(--sl-nav-height) + 0.5rem);
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-block: 1rem 2rem;
  padding: 0.625rem 0.75rem;
  background-color: var(--sl-color-gray-6);
  border: 1px solid var(--sl-color-hairline-light);
  border-radius: var(--bl-radius-2);
}

.fj-filter input {
  flex: 1;
  min-width: 0;
  padding: 0.4375rem 0.625rem;
  font: inherit;
  font-size: var(--sl-text-sm);
  color: var(--sl-color-white);
  background-color: var(--sl-color-bg);
  border: 1px solid var(--sl-color-hairline-light);
  border-radius: var(--bl-radius-1);
}

.fj-filter input::placeholder {
  color: var(--sl-color-gray-3);
}

.fj-filter output {
  font-family: var(--sl-font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--sl-color-gray-3);
  white-space: nowrap;
}

.fj-features {
  table-layout: fixed;
}

.fj-features th:nth-child(1) {
  width: 26%;
}

.fj-features th:nth-child(3) {
  width: 30%;
}

.fj-features td {
  overflow-wrap: anywhere;
}

.fj-features td.fj-where {
  color: var(--sl-color-gray-2);
  font-size: 0.8125rem;
}

.fj-section[hidden],
.fj-features tr[hidden] {
  display: none;
}
/* -----------------------------------------------------------------------------
   Boppa Llewyn web fonts, self-hosted.

   Cormorant Garamond is the display face, IBM Plex Sans the body/UI face and
   IBM Plex Mono the eyebrow/code face. The files in /public/fonts are the
   `latin` and `latin-ext` WOFF2 subsets published by Google Fonts, split by
   unicode-range exactly as Google serves them, so a page of English text only
   downloads the `latin` file. Licences: /public/fonts/OFL.txt.

   Registered ahead of custom.css in astro.config.mjs so the @font-face rules
   are parsed before anything asks for the families.
   -------------------------------------------------------------------------- */

@font-face {
  font-family: 'Cormorant Garamond';
  src: url('/fonts/CormorantGaramond-Variable-latin.woff2') format('woff2');
  font-weight: 300 700;
  font-style: normal;
  font-display: swap;
  unicode-range:
    U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329,
    U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}

@font-face {
  font-family: 'Cormorant Garamond';
  src: url('/fonts/CormorantGaramond-Variable-latin-ext.woff2') format('woff2');
  font-weight: 300 700;
  font-style: normal;
  font-display: swap;
  unicode-range:
    U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329,
    U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C0, U+2113, U+2C60-2C7F,
    U+A720-A7FF;
}

@font-face {
  font-family: 'Cormorant Garamond';
  src: url('/fonts/CormorantGaramond-Italic-Variable-latin.woff2') format('woff2');
  font-weight: 300 700;
---
// One screen of the app, captured in both looks; the page's theme shows the matching one.
// `name` is a capture's file name without its look: `05-clip-picture.inspector` reads
// src/assets/screens/05-clip-picture.inspector.{light,dark}.webp. An unknown name fails the build.
// A capture is at 2× and never shows larger than its real size, so a sheet looks like a sheet.
import { Image } from 'astro:assets';
import type { ImageMetadata } from 'astro';

interface Props {
  name: string;
  alt: string;
  caption?: string;
}

const { name, alt, caption } = Astro.props;

const screens = import.meta.glob<{ default: ImageMetadata }>('../assets/screens/*.webp', {
  eager: true,
});

function shot(look: 'light' | 'dark') {
  const found = screens[`../assets/screens/${name}.${look}.webp`];
  if (!found) throw new Error(`Shot: no ${look} capture named "${name}" in src/assets/screens/`);
  return found.default;
}

const light = shot('light');
const dark = shot('dark');
---

<figure class="fj-shot" style={`max-width: ${Math.round(light.width / 2)}px`}>
  <Image class="fj-light" src={light} alt={alt} />
  <Image class="fj-dark" src={dark} alt={alt} />
  {caption && <figcaption>{caption}</figcaption>}
</figure>
---
/* Boppa Llewyn header lockup, as on Doctored's site: the mark, the wordmark in
   Cormorant Garamond and a mono version badge. Starlight's own SiteTitle renders
   the logo image and the title text only, and cannot carry the badge. */
import { Image } from 'astro:assets';
import { logos } from 'virtual:starlight/user-images';
import config from 'virtual:starlight/user-config';
import { APP_VERSION } from '../site';

/* The mark is an SVG drawn on a 1024px square: the header shows it at 24pt, and one file serves
   every pixel density, so it takes no `densities`. */
const iconAttrs = { width: 24, height: 24, alt: config.logo?.alt ?? '' };

const { siteTitle, siteTitleHref } = Astro.locals.starlightRoute;
---

<a href={siteTitleHref} class="site-title sl-flex">
  {logos.dark && (
    <Image
      src={logos.dark}
      {...iconAttrs}
      class:list={{ 'light:sl-hidden': Boolean(logos.light && logos.light !== logos.dark) }}
    />
  )}
  {logos.light && logos.light !== logos.dark && (
    <Image src={logos.light} {...iconAttrs} class="dark:sl-hidden" />
  )}
  <span class="wordmark" translate="no">
    {siteTitle}
  </span>
  <span class="version" translate="no">
    v{APP_VERSION}
  </span>
</a>

<style>
  @layer starlight.core {
    .site-title {
      align-items: center;
      gap: 0.625rem;
      color: var(--sl-color-white);
      text-decoration: none;
      white-space: nowrap;
      min-width: 0;
    }

    .wordmark {
      overflow: hidden;
    }

    img {
      width: 1.5rem;
      height: 1.5rem;
      flex-shrink: 0;
      object-fit: contain;
    }

    .version {
      flex-shrink: 0;
      font-family: var(--sl-font-mono);
      font-size: 0.6875rem;
      font-weight: 400;
      line-height: 1;
      color: var(--sl-color-gray-3);
      border: 1px solid var(--sl-color-hairline-light);
      border-radius: var(--bl-radius-1);
      padding: 0.1875rem 0.3125rem;
    }
  }
</style>

