  color: var(--sl-color-white);
  background-color: var(--sl-color-bg);
  border: 1px solid var(--sl-color-hairline-light);
  border-radius: var(--bl-radius-1);
}

.fj-filter input::placeholder {
  color: var(--sl-color-gray-3);
}

.fj-filter output {
  font-family: var(--sl-font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--sl-color-gray-3);
  white-space: nowrap;
}

.fj-features {
  table-layout: fixed;
}

.fj-features th:nth-child(1) {
  width: 26%;
}

.fj-features th:nth-child(3) {
  width: 30%;
}

.fj-features td {
  overflow-wrap: anywhere;
}

.fj-features td.fj-where {
  color: var(--sl-color-gray-2);
  font-size: 0.8125rem;
}

.fj-section[hidden],
.fj-features tr[hidden] {
  display: none;
}
/* -----------------------------------------------------------------------------
   Boppa Llewyn web fonts, self-hosted.

   Cormorant Garamond is the display face, IBM Plex Sans the body/UI face and
   IBM Plex Mono the eyebrow/code face. The files in /public/fonts are the
   `latin` and `latin-ext` WOFF2 subsets published by Google Fonts, split by
   unicode-range exactly as Google serves them, so a page of English text only
   downloads the `latin` file. Licences: /public/fonts/OFL.txt.

   Registered ahead of custom.css in astro.config.mjs so the @font-face rules
   are parsed before anything asks for the families.
   -------------------------------------------------------------------------- */

@font-face {
  font-family: 'Cormorant Garamond';
  src: url('/fonts/CormorantGaramond-Variable-latin.woff2') format('woff2');
  font-weight: 300 700;
  font-style: normal;
  font-display: swap;
  unicode-range:
    U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329,
    U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}

@font-face {
  font-family: 'Cormorant Garamond';
  src: url('/fonts/CormorantGaramond-Variable-latin-ext.woff2') format('woff2');
  font-weight: 300 700;
  font-style: normal;
  font-display: swap;
  unicode-range:
    U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329,
    U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C0, U+2113, U+2C60-2C7F,
    U+A720-A7FF;
}

@font-face {
  font-family: 'Cormorant Garamond';
  src: url('/fonts/CormorantGaramond-Italic-Variable-latin.woff2') format('woff2');
  font-weight: 300 700;
---
// One screen of the app, captured in both looks; the page's theme shows the matching one.
// `name` is a capture's file name without its look: `05-clip-picture.inspector` reads
// src/assets/screens/05-clip-picture.inspector.{light,dark}.webp. An unknown name fails the build.
// A capture is at 2× and never shows larger than its real size, so a sheet looks like a sheet.
import { Image } from 'astro:assets';
import type { ImageMetadata } from 'astro';

interface Props {
  name: string;
  alt: string;
  caption?: string;
}

const { name, alt, caption } = Astro.props;

const screens = import.meta.glob<{ default: ImageMetadata }>('../assets/screens/*.webp', {
  eager: true,
});

function shot(look: 'light' | 'dark') {
  const found = screens[`../assets/screens/${name}.${look}.webp`];
  if (!found) throw new Error(`Shot: no ${look} capture named "${name}" in src/assets/screens/`);
  return found.default;
}

const light = shot('light');
const dark = shot('dark');
---

<figure class="fj-shot" style={`max-width: ${Math.round(light.width / 2)}px`}>
  <Image class="fj-light" src={light} alt={alt} />
  <Image class="fj-dark" src={dark} alt={alt} />
  {caption && <figcaption>{caption}</figcaption>}
</figure>
---
/* Boppa Llewyn header lockup, as on Doctored's site: the mark, the wordmark in
   Cormorant Garamond and a mono version badge. Starlight's own SiteTitle renders
   the logo image and the title text only, and cannot carry the badge. */
import { Image } from 'astro:assets';
import { logos } from 'virtual:starlight/user-images';
import config from 'virtual:starlight/user-config';
import { APP_VERSION } from '../site';

/* The mark is an SVG drawn on a 1024px square: the header shows it at 24pt, and one file serves
   every pixel density, so it takes no `densities`. */
const iconAttrs = { width: 24, height: 24, alt: config.logo?.alt ?? '' };

const { siteTitle, siteTitleHref } = Astro.locals.starlightRoute;
---

<a href={siteTitleHref} class="site-title sl-flex">
  {logos.dark && (
    <Image
      src={logos.dark}
      {...iconAttrs}
      class:list={{ 'light:sl-hidden': Boolean(logos.light && logos.light !== logos.dark) }}
    />
  )}
  {logos.light && logos.light !== logos.dark && (
    <Image src={logos.light} {...iconAttrs} class="dark:sl-hidden" />
  )}
  <span class="wordmark" translate="no">
    {siteTitle}
  </span>
  <span class="version" translate="no">
    v{APP_VERSION}
  </span>
</a>

<style>
  @layer starlight.core {
    .site-title {
      align-items: center;
      gap: 0.625rem;
      color: var(--sl-color-white);
      text-decoration: none;
      white-space: nowrap;
      min-width: 0;
    }

    .wordmark {
      overflow: hidden;
    }

    img {
      width: 1.5rem;
      height: 1.5rem;
      flex-shrink: 0;
      object-fit: contain;
    }

    .version {
      flex-shrink: 0;
      font-family: var(--sl-font-mono);
      font-size: 0.6875rem;
      font-weight: 400;
      line-height: 1;
      color: var(--sl-color-gray-3);
      border: 1px solid var(--sl-color-hairline-light);
      border-radius: var(--bl-radius-1);
      padding: 0.1875rem 0.3125rem;
    }
  }
</style>

content.content:
---
/* The system has exactly two surfaces — warm ebony and cream — so the stock
   three-option auto/light/dark <select> becomes a two-state toggle. The stored
   key and the `data-theme` attribute stay Starlight's, so ThemeProvider's
   no-FOUC inline script keeps working unchanged. */
import { Icon } from '@astrojs/starlight/components';
---

<starlight-theme-select>
  <button type="button" class="theme-toggle">
    <Icon name="moon" class="icon-dark" size="1rem" />
    <Icon name="sun" class="icon-light" size="1rem" />
    <span class="sr-only">{Astro.locals.t('themeSelect.accessibleLabel')}</span>
  </button>
</starlight-theme-select>

<script>
  /** Key in `localStorage` to store colour theme preference at — Starlight's own. */
  const storageKey = 'starlight-theme';

  const currentTheme = (): 'dark' | 'light' =>
    document.documentElement.dataset.theme === 'light' ? 'light' : 'dark';

  class StarlightThemeSelect extends HTMLElement {
    constructor() {
      super();
      const button = this.querySelector('button');
      if (!button) return;
      const label = () => {
        // Name the destination, not the state: this is a control, not a status.
        button.setAttribute(
          'aria-label',
          currentTheme() === 'dark' ? 'Use the light theme' : 'Use the dark theme',
        );
      };
      label();
      button.addEventListener('click', () => {
        const next = currentTheme() === 'dark' ? 'light' : 'dark';
        document.documentElement.dataset.theme = next;
        try {
          localStorage.setItem(storageKey, next);
        } catch {}
        label();
      });
    }
  }
  customElements.define('starlight-theme-select', StarlightThemeSelect);
</script>

<style>
  @layer starlight.core {
    .theme-toggle {
      position: relative;
      display: flex;
      align-items: center;
      justify-content: center;
      width: 2rem;
      height: 2rem;
      padding: 0;
      border: 1px solid var(--sl-color-hairline-light);
      border-radius: var(--bl-radius-1);
      background-color: transparent;
      color: var(--sl-color-gray-2);
      cursor: pointer;
    }

    .theme-toggle:hover {
      background-color: var(--sl-color-gray-6);
      border-color: var(--sl-color-gray-4);
      color: var(--sl-color-white);
    }

    /* 32px box, 44px target. */
    .theme-toggle::after {
      content: '';
      position: absolute;
      inset: -0.375rem;
    }

    /* Show the surface you are on, not the one you would switch to. */
    .icon-light {
      display: none;
    }

    :global(:root[data-theme='light']) .icon-dark {
      display: none;
    }

    :global(:root[data-theme='light']) .icon-light {
      display: block;
    }
  }
</style>
---
/* The system's standard page opener: a mono uppercase eyebrow naming the
   section, the h1, then the page description. Starlight renders the h1 alone
   and puts the description in <head> only. */
import type { StarlightRouteData } from '@astrojs/starlight/route-data';

/** Starlight's id for the top-of-page anchor the skip link targets. */
const PAGE_TITLE_ID = '_top';

const { entry, sidebar } = Astro.locals.starlightRoute;

/** The label of the sidebar group the current page sits in, if any. */
function currentGroupLabel(
  entries: StarlightRouteData['sidebar'],
  label?: string,
): string | undefined {
  for (const item of entries) {
    if (item.type === 'link') {
      if (item.isCurrent) return label;
    } else {
      const found = currentGroupLabel(item.entries, item.label);
      if (found) return found;
    }
  }
  return undefined;
}

const eyebrow = entry.data.eyebrow ?? currentGroupLabel(sidebar);
const { description } = entry.data;
---

{eyebrow && <p class="page-eyebrow">{eyebrow}</p>}
<h1 id={PAGE_TITLE_ID}>{entry.data.title}</h1>
{description && <p class="page-description">{description}</p>}

<style>
  @layer starlight.core {
    h1 {
      font-size: var(--sl-text-h1);
      line-height: var(--sl-line-height-headings);
    }

    .page-eyebrow + h1 {
      margin-top: 1.25rem;
    }

    h1 + .page-description {
      margin-top: 1rem;
    }
  }
</style>
---
/* Starlight's Hero, plus the mono eyebrow the system puts above every h1.
   The layout below is Starlight's own, kept because overriding a component
   replaces its scoped CSS; the design's splash values live in custom.css. */
import { Image } from 'astro:assets';
import DraftContentNotice from '@astrojs/starlight/components/DraftContentNotice.astro';
import { LinkButton } from '@astrojs/starlight/components';

/** Starlight's id for the top-of-page anchor the skip link targets. */
const PAGE_TITLE_ID = '_top';

const { data } = Astro.locals.starlightRoute.entry;
const { title = data.title, tagline, image, actions = [] } = data.hero || {};
const { eyebrow } = data;

const imageAttrs = {
  loading: 'eager' as const,
  decoding: 'async' as const,
  width: 400,
  height: 400,
  alt: image?.alt || '',
};

let darkImage: ImageMetadata | undefined;
let lightImage: ImageMetadata | undefined;
let rawHtml: string | undefined;
if (image) {
  if ('file' in image) {
    darkImage = image.file;
  } else if ('dark' in image) {
    darkImage = image.dark;
    lightImage = image.light;
  } else {
    rawHtml = image.html;
  }
}
---

<div class="hero">
  {darkImage && (
    <Image
      src={darkImage}
      {...imageAttrs}
      class:list={{ 'light:sl-hidden': Boolean(lightImage) }}
    />
  )}
  {lightImage && <Image src={lightImage} {...imageAttrs} class="dark:sl-hidden" />}
  {rawHtml && <div class="hero-html sl-flex" set:html={rawHtml} />}
  <div class="sl-flex stack">
    <div class="sl-flex copy">
      {eyebrow && <p class="page-eyebrow">{eyebrow}</p>}
      <h1 id={PAGE_TITLE_ID} data-page-title set:html={title} />
      {data.draft && <DraftContentNotice />}
      {tagline && <div class="tagline" set:html={tagline} />}
    </div>
    {actions.length > 0 && (
      <div class="sl-flex actions">
        {actions.map(
          ({ attrs: { class: className, ...attrs } = {}, icon, link: href, text, variant }) => (
            <LinkButton {href} {variant} icon={icon?.name} class:list={[className]} {...attrs}>
              {text}
              {icon?.html && <Fragment set:html={icon.html} />}
            </LinkButton>
          ),
        )}
      </div>
    )}
  </div>
</div>

<style>
  @layer starlight.core {
    .hero {
      display: grid;
      grid-template-columns: 100%;
      align-items: center;
      gap: 1rem;
      padding-bottom: 1rem;
    }

    .hero > img,
    .hero > .hero-html {
      object-fit: contain;
      width: min(70%, 20rem);
      height: auto;
      margin-inline: auto;
    }

    .stack {
      flex-direction: column;
      gap: clamp(1.5rem, calc(1.5rem + 1vw), 2rem);
      text-align: center;
    }

    .copy {
      flex-direction: column;
      gap: 1rem;
      align-items: center;
    }

    .copy > * {
      max-width: 50ch;
    }

    .page-eyebrow + h1 {
      margin-top: 0.25rem;
    }

    h1 {
      font-size: clamp(var(--sl-text-3xl), calc(0.25rem + 5vw), var(--sl-text-6xl));
      line-height: var(--sl-line-height-headings);
      color: var(--sl-color-white);
    }

    .tagline {
      color: var(--sl-color-gray-2);
    }

    .actions {
      gap: 1rem 2rem;
      flex-wrap: wrap;
      justify-content: center;
    }

    @media (min-width: 50rem) {
      .hero {
        grid-template-columns: 7fr 4fr;
        gap: 3%;
        padding-block: clamp(2.5rem, calc(1rem + 10vmin), 10rem);
      }

      .hero > img,
      .hero > .hero-html {
        order: 2;
        width: min(100%, 25rem);
      }

      .stack {
        text-align: start;
      }

      .copy {
        align-items: flex-start;
      }

      .actions {
        justify-content: flex-start;
      }
    }
  }
</style>

