---
import { sidebarGroupHasCurrent } from '../utils/navigation';
import type { SidebarEntry } from '../utils/routing/types';
import Icon from '../user-components/Icon.astro';
import Badge from '../user-components/Badge.astro';
import SidebarRestorePoint from './SidebarRestorePoint.astro';

interface Props {
	sublist: SidebarEntry[];
	nested?: boolean;
}

const { sublist, nested } = Astro.props;
---

<ul class:list={{ 'top-level': !nested }}>
	{sublist.map((entry) => <li>
		{entry.type === 'link' ? (
			<a
				href={entry.href}
				aria-current={entry.isCurrent ? 'page' : undefined}
				class:list={[{ large: !nested }, entry.attrs.class]}
				{...entry.attrs}
			>
				<span>{entry.label}</span>
				{entry.badge && (
					<Badge variant={entry.badge.variant} class={entry.badge.class} text={entry.badge.text} />
				)}
			</a>
		) : (
			<details open={sidebarGroupHasCurrent(entry) || !entry.collapsed}>
				<summary>
					<span class="group-label">
						<span class="large">{entry.label}</span>
						{entry.badge && (
							<Badge
								variant={entry.badge.variant}
								class={entry.badge.class}
								text={entry.badge.text}
							/>
						)}
					</span>
					<Icon name="right-caret" class="caret" size="1.25rem" />
				</summary>
				<SidebarRestorePoint />
				<Astro.self sublist={entry.entries} nested />
			</details>
		)}
	</li>)}
</ul>

