cd /Users/kevingalligan/devel/framejob-ai-docs-int/docs/site && python3 - <<'EOF'
p='src/components/ThemeSelect.astro'
s=open(p).read()
a="""/* The system has exactly two surfaces — warm ebony and cream — so the stock
   three-option auto/light/dark <select> becomes a two-state toggle. The stored
   key and the `data-theme` attribute stay Starlight's, so ThemeProvider's
   no-FOUC inline script keeps working unchanged. */"""
b="""/* The site has exactly two looks, Neutral Light and Neutral Dark, so the stock
   three-option auto/light/dark <select> becomes a two-state toggle: a 36px ghost
   button like the header's other icon buttons. The stored key and the
   `data-theme` attribute stay Starlight's, so ThemeProvider's no-FOUC inline
   script keeps working unchanged. */"""
assert s.count(a)==1; s=s.replace(a,b)
i=s.index('<style>')
s=s[:i]+"""<style>
  @layer starlight.core {
    .theme-toggle {
      position: relative;
      display: flex;
      align-items: center;
      justify-content: center;
      width: 2.25rem;
      height: 2.25rem;
      padding: 0;
      border: 0;
      border-radius: var(--bl-radius-md);
      background-color: transparent;
      color: var(--bl-ink-muted);
      cursor: pointer;
    }

    .theme-toggle:hover {
      background-color: var(--bl-surface-sunken);
      color: var(--bl-ink);
    }

    .theme-toggle :global(svg) {
      width: 1.125rem;
      height: 1.125rem;
    }

    /* 36px box, 44px target. */
    .theme-toggle::after {
      content: '';
      position: absolute;
      inset: -0.25rem;
    }

    /* Show the look you are in, not the one you would switch to. */
    .icon-light {
      display: none;
    }

    :global(:root[data-theme='light']) .icon-dark {
      display: none;
    }

    :global(:root[data-theme='light']) .icon-light {
      display: block;
    }
  }
</style>
"""
open(p,'w').write(s)

p='src/components/PageTitle.astro'
s=open(p).read()
a="""/* The system's standard page opener: a mono uppercase eyebrow naming the
   section, the h1, then the page description. Starlight renders the h1 alone
   and puts the description in <head> only. */"""
b="""/* The system's standard page opener: a mono uppercase eyebrow naming the
   section 12px above the h1, then the page description 16px below it.
   Starlight renders the h1 alone and puts the description in <head> only. The
   type is boppa-llewyn.css's. */"""
assert s.count(a)==1; s=s.replace(a,b)
a="""    .page-eyebrow + h1 {
      margin-top: 1.25rem;
    }"""
b="""    .page-eyebrow + h1 {
      margin-top: 0.75rem;
    }"""
assert s.count(a)==1; s=s.replace(a,b)
open(p,'w').write(s)

p='src/components/Hero.astro'
s=open(p).read()
a="""/* Starlight's Hero, plus the mono eyebrow the system puts above every h1.
   The layout below is Starlight's own, kept because overriding a component
   replaces its scoped CSS; the design's splash values live in custom.css. */"""
b="""/* Starlight's Hero, plus the mono eyebrow the system puts above every h1.
   The layout below is Starlight's own, kept because overriding a component
   replaces its scoped CSS; the design's splash values (the full-width band,
   the 1fr 192px columns, the display title) live in boppa-llewyn.css. */"""
assert s.count(a)==1; s=s.replace(a,b)
open(p,'w').write(s)
