toolUseResult.originalFile:
/* Frame Job's own components in the Boppa Llewyn design system (tokens.css holds every --bl-*
   token used here; boppa-llewyn.css, which loads first, maps them onto Starlight): hairline boxes
   on the surface, mono uppercase eyebrows for labels, the card shadow on a screen and the window
   shadow on a framed one, and the system's 6/10/16px corners. Unlayered, like the theme. */

/* ---- Screens: both looks are in the page, the theme shows one. ---- */

.fj-shot {
  margin: 2rem 0 0;
}

.fj-shot img {
  display: block;
  width: 100%;
  height: auto;
  border: 1px solid var(--bl-line);
  border-radius: var(--bl-radius-md);
  box-shadow: var(--bl-shadow-card);
}

.fj-shot figcaption {
  margin-top: 0.625rem;
  font-size: 0.875rem;
  line-height: 1.25rem;
  color: var(--bl-ink-subtle);
  text-align: center;
}

:root[data-theme='light'] .fj-shot .fj-dark,
:root:not([data-theme='light']) .fj-shot .fj-light {
  display: none;
}

/* A full-window capture in a window frame: a 36px title bar with three dots in the hairline
   colour and the title centred, the large corner and the site's only large shadow. */

.fj-window {
  overflow: hidden;
  background-color: var(--bl-surface);
  border-radius: var(--bl-radius-lg);
  box-shadow: var(--bl-shadow-window);
}

.fj-window-bar {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  height: 2.25rem;
  padding: 0 0.875rem;
  border-bottom: 1px solid var(--bl-line);
}

.fj-window-dot {
  flex: none;
  width: 0.75rem;
  height: 0.75rem;
  border-radius: 50%;
  background-color: var(--bl-line);
}

/* The right margin is the dots' width (3 × 12px + 2 × 8px), so the title centres on the bar. */
.fj-window-title {
  flex: 1;
  min-width: 0;
  margin-right: 3.25rem;
  overflow: hidden;
  font-size: 0.8125rem;
  font-weight: 500;
  line-height: 1rem;
  color: var(--bl-ink-subtle);
  text-align: center;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.fj-shot--framed img {
  border: 0;
  border-radius: 0;
  box-shadow: none;
}

/* ---- Keys, as the app prints them: ⌘T. The theme styles the key cap itself. ---- */

.sl-markdown-content kbd {
  white-space: nowrap;
}

/* ---- At a glance: a hairline box on the surface, its labels mono eyebrows. ---- */

.fj-glance {
  display: grid;
  grid-template-columns: max-content 1fr;
  align-items: baseline;
  gap: 0.625rem 1.5rem;
  margin-block: 2rem 0;
  padding: 1rem 1.25rem;
  background-color: var(--bl-surface);
  border: 1px solid var(--bl-line);
  border-radius: var(--bl-radius-md);
  font-size: 0.9375rem;
  line-height: 1.5rem; /* 15 / 24 */
  color: var(--bl-ink);
}

.fj-glance dt {
  margin: 0;
  font-family: var(--sl-font-mono);
  font-weight: 500;
  font-size: 0.75rem;
  line-height: 1.5rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--bl-ink-subtle);
}

.fj-glance dd {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.25rem 0.625rem;
  margin: 0;
}

.fj-glance strong {
  font-weight: 600;
  color: var(--bl-ink);
}

.fj-glance code {
  font-size: 0.8125rem;
  background-color: var(--bl-surface-sunken);
  border-radius: var(--bl-radius-sm);
  padding: 0.125rem 0.3125rem;
}

/* ---- The feature index: a filter box above tables drawn as the theme's tables. ---- */

.fj-filter {
  position: sticky;
  top: calc(var(--sl-nav-height) + 0.5rem);
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-block: 1rem 2rem;
  padding: 0.625rem 0.75rem;
  background-color: var(--bl-surface);
  border: 1px solid var(--bl-line);
  border-radius: var(--bl-radius-md);
}

.fj-filter input {
  flex: 1;
  min-width: 0;
  padding: 0.4375rem 0.625rem;
  font: inherit;
  font-size: 0.875rem;
  line-height: 1.25rem;
  color: var(--bl-ink);
  background-color: var(--bl-bg);
  border: 1px solid var(--bl-line-strong);
  border-radius: var(--bl-radius-sm);
}

.fj-filter input::placeholder {
  font-size: 0.875rem;
  color: var(--bl-ink-subtle);
}

.fj-filter output {
  font-family: var(--sl-font-mono);
  font-size: 0.75rem;
  line-height: 1rem;
  color: var(--bl-ink-subtle);
  white-space: nowrap;
}

.fj-features {
  table-layout: fixed;
}

.fj-features th:nth-child(1) {
  width: 26%;
}

.fj-features th:nth-child(3) {
  width: 30%;
}

.fj-features td {
  overflow-wrap: anywhere;
}

.fj-features td.fj-where {
  color: var(--bl-ink-muted);
  font-size: 0.875rem;
  line-height: 1.25rem;
}

.fj-section[hidden],
.fj-features tr[hidden] {
  display: none;
}

